const CSS = `
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Instrument+Serif:ital@0;1&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--void:#080b0b;--ash:#0f1413;--panel:#141a18;--panel-hi:#1a211f;--line:rgba(232,247,228,.09);--text:#f2f7f0;--muted:#89948d;--soft:#535d57;--acid:#baff35;--mint:#4cf2a6;--lime-dim:rgba(186,255,53,.12);--mint-dim:rgba(76,242,166,.12);--amber:#ffb54c;--rose:#ff7070;--radius:23px;--ease:cubic-bezier(.2,.8,.2,1)}
*{box-sizing:border-box}body{margin:0;background:var(--void);color:var(--text);font-family:Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}button,input,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--acid);outline-offset:3px}.shell{min-height:100vh;background:radial-gradient(circle at 75% -18%,rgba(76,242,166,.1),transparent 30%),var(--void)}
/* Brand */
.logo{display:inline-flex;align-items:center;gap:10px;color:var(--text);font-size:17px;font-weight:800;letter-spacing:-.06em}.logo svg{filter:drop-shadow(0 0 12px rgba(186,255,53,.22))}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(135deg,rgba(76,242,166,.14),rgba(186,255,53,.06));border:1px solid rgba(186,255,53,.16)}
/* Landing */
.landing{min-height:100vh;overflow:hidden;position:relative;background:linear-gradient(155deg,#080b0b 0%,#0b100e 45%,#101a13 100%)}.landing:before{content:"";position:absolute;width:680px;height:680px;border-radius:50%;right:-280px;top:180px;background:radial-gradient(circle,rgba(186,255,53,.2),transparent 66%);filter:blur(18px);pointer-events:none}.landing-nav{height:86px;padding:0 max(22px,calc((100vw - 1280px)/2));display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:2}.nav-link{border:0;background:none;color:var(--muted);font-size:13px;font-weight:700}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border-radius:14px;border:1px solid transparent;padding:12px 16px;color:var(--text);font-weight:800;font-size:13px;transition:transform 160ms var(--ease),background 160ms var(--ease),border-color 160ms var(--ease)}.btn:active{transform:scale(.97)}.btn-acid{background:var(--acid);color:#101608;box-shadow:0 10px 25px rgba(186,255,53,.18)}.btn-quiet{background:rgba(255,255,255,.035);border-color:var(--line);color:var(--text)}.btn-outline{background:transparent;border-color:rgba(186,255,53,.45);color:var(--acid)}.btn-rose{background:rgba(255,112,112,.1);border-color:rgba(255,112,112,.25);color:#ff9c9c}.btn-sm{padding:9px 12px;border-radius:11px;font-size:12px}.btn-full{width:100%}
.landing-main{max-width:1280px;margin:auto;padding:clamp(70px,10vw,136px) 28px 58px;display:grid;grid-template-columns:1.05fr .95fr;gap:54px;align-items:center;position:relative;z-index:1}.eyebrow{display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:800;letter-spacing:.15em;text-transform:uppercase;color:var(--acid)}.hero h1{font-family:'Instrument Serif',Georgia,serif;font-size:clamp(58px,7vw,104px);letter-spacing:-.065em;line-height:.84;font-weight:400;margin:18px 0 26px;max-width:720px}.hero h1 em{font-style:italic;color:var(--acid)}.hero-copy{max-width:500px;color:var(--muted);font-size:16px;line-height:1.75;margin:0 0 30px}.hero-cta{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.hero-note{font-size:11px;color:var(--soft);margin-top:17px}.hero-art{position:relative;min-height:510px}.money-orbit{position:absolute;width:min(470px,100%);aspect-ratio:1;right:0;top:0;border-radius:46% 54% 51% 49% / 44% 47% 53% 56%;background:linear-gradient(140deg,rgba(186,255,53,.12),rgba(76,242,166,.02) 55%,rgba(255,255,255,.03));border:1px solid rgba(186,255,53,.18);transform:rotate(-11deg);overflow:hidden}.money-orbit:after{content:"";width:260px;height:260px;border-radius:50%;position:absolute;right:-55px;bottom:-76px;background:rgba(76,242,166,.16);filter:blur(18px)}.hero-card{position:absolute;background:rgba(15,20,19,.9);backdrop-filter:blur(16px);border:1px solid rgba(232,247,228,.12);box-shadow:0 28px 80px rgba(0,0,0,.32);border-radius:20px}.hero-card.main{width:365px;right:32px;top:70px;padding:21px}.hero-card.small{width:244px;left:0;bottom:25px;padding:17px;transform:rotate(-4deg)}.mini-label{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--soft);font-weight:800}.mini-money{font-family:'DM Mono',monospace;font-size:26px;letter-spacing:-.08em;margin:10px 0 18px}.track{height:7px;border-radius:99px;background:rgba(255,255,255,.07);overflow:hidden}.track i{display:block;width:64%;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--mint),var(--acid))}.hero-chip{display:flex;align-items:center;gap:9px;padding:11px 0;border-top:1px solid var(--line);font-size:12px;font-weight:700}.hero-chip:first-of-type{border:0}.avatar-dot{width:28px;height:28px;border-radius:9px;background:linear-gradient(135deg,#4cf2a6,#baff35);color:#142010;display:grid;place-items:center;font-size:11px}.trust-line{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;line-height:1.45}.trust-line svg{color:var(--acid);flex:none}.landing-detail{max-width:1280px;margin:auto;padding:20px 28px 72px;display:grid;grid-template-columns:.82fr 1.18fr;gap:18px;align-items:stretch}.detail-intro{padding:28px 6px}.detail-intro h2{font-family:'Instrument Serif',Georgia,serif;font-size:clamp(38px,4.6vw,64px);font-weight:400;letter-spacing:-.06em;line-height:.92;margin:13px 0 16px;max-width:520px}.detail-intro p{color:var(--muted);font-size:13px;line-height:1.7;max-width:390px;margin:0}.pulse-board{min-height:290px;position:relative;overflow:hidden;border:1px solid rgba(76,242,166,.16);border-radius:23px;padding:22px;background:linear-gradient(145deg,rgba(76,242,166,.1),rgba(255,255,255,.018) 48%,rgba(186,255,53,.045))}.pulse-board:after{content:"";position:absolute;right:-65px;bottom:-90px;width:240px;height:240px;border-radius:50%;background:rgba(186,255,53,.13);filter:blur(20px)}.pulse-board>*{position:relative;z-index:1}.pulse-head{display:flex;align-items:flex-start;justify-content:space-between}.pulse-head b{display:block;font-size:13px;margin-top:5px}.pulse-kicker{font-family:'DM Mono',monospace;font-size:9px;color:var(--acid);letter-spacing:.1em}.pulse-stamp{font-size:9px;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:6px 8px}.pulse-bars{height:118px;display:flex;align-items:flex-end;gap:10px;margin:23px 0 16px;padding:0 3px;border-bottom:1px solid rgba(232,247,228,.14)}.pulse-bar{flex:1;min-width:12px;border-radius:7px 7px 0 0;background:linear-gradient(180deg,var(--acid),rgba(76,242,166,.28));opacity:.85}.pulse-bar.dim{opacity:.3}.pulse-labels{display:flex;justify-content:space-between;color:var(--muted);font-size:9px}.pulse-tags{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}.pulse-tag{font-size:10px;padding:7px 9px;border-radius:9px;background:rgba(8,11,11,.38);border:1px solid var(--line);color:var(--muted)}.pulse-tag strong{color:var(--text);margin-right:4px}.landing-footer{max-width:1280px;padding:0 28px 60px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.principle{padding:21px 20px 23px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.018)}.principle-index{display:block;color:var(--acid);font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.1em;margin-bottom:22px}.principle b{display:block;font-size:15px;margin-bottom:7px}.principle p{margin:0;color:var(--muted);line-height:1.6;font-size:12px}
/* App shell */
.app{min-height:100vh;display:flex}.rail{width:246px;position:fixed;inset:0 auto 0 0;background:rgba(12,16,15,.94);border-right:1px solid var(--line);padding:24px 14px;display:flex;flex-direction:column;z-index:30;backdrop-filter:blur(18px)}.rail .logo{padding:0 10px;margin-bottom:45px}.nav-group{display:flex;flex-direction:column;gap:4px}.nav-item{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;border-radius:13px;padding:12px;color:var(--muted);font-size:13px;font-weight:700;text-align:left}.nav-item:hover{background:rgba(255,255,255,.035);color:var(--text)}.nav-item.active{background:linear-gradient(100deg,rgba(186,255,53,.15),rgba(186,255,53,.035));color:var(--acid)}.nav-item .counter{margin-left:auto;width:19px;height:19px;border-radius:50%;display:grid;place-items:center;background:var(--amber);color:#211506;font-size:10px}.rail-foot{margin-top:auto;padding:13px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(150deg,rgba(76,242,166,.08),rgba(255,255,255,.01))}.agent-status{display:flex;gap:8px;align-items:center;font-size:11px;font-weight:800;color:var(--acid);margin-bottom:7px}.pulse{width:8px;height:8px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 4px rgba(186,255,53,.1)}.rail-foot p{color:var(--muted);font-size:10px;line-height:1.5;margin:0}.app-main{width:calc(100% - 246px);margin-left:246px;min-height:100vh}.topbar{height:82px;padding:0 42px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:rgba(8,11,11,.78);backdrop-filter:blur(18px);position:sticky;top:0;z-index:20}.page-title h1{font-size:16px;letter-spacing:-.04em;margin:0;font-weight:800}.page-title p{margin:3px 0 0;color:var(--soft);font-size:11px}.top-actions{display:flex;align-items:center;gap:9px}.icon-btn{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;border:1px solid var(--line);background:var(--ash);color:var(--muted);position:relative}.notify-dot{position:absolute;width:6px;height:6px;border-radius:50%;right:9px;top:8px;background:var(--acid)}.profile-button{width:38px;height:38px;border:0;border-radius:12px;background:linear-gradient(135deg,var(--mint),var(--acid));color:#13200d;font-weight:800}.content{max-width:1360px;margin:auto;padding:38px 42px 90px}
/* Home */
.home-grid{display:grid;grid-template-columns:minmax(0,1.18fr) 320px;gap:18px;align-items:start}.balance-stage{position:relative;overflow:hidden;min-height:330px;border-radius:var(--radius);padding:27px;background:linear-gradient(128deg,#16311e 0%,#0f1d17 53%,#131815 100%);border:1px solid rgba(186,255,53,.21)}.balance-stage:before{content:"";position:absolute;width:430px;height:430px;border-radius:50%;right:-175px;top:-215px;background:radial-gradient(circle,rgba(186,255,53,.34),transparent 65%);filter:blur(5px)}.stage-head,.balance-copy,.stage-actions,.plan-card{position:relative;z-index:1}.stage-head{display:flex;align-items:center;justify-content:space-between}.active-pill{display:inline-flex;align-items:center;gap:7px;border:1px solid rgba(186,255,53,.25);background:rgba(186,255,53,.09);border-radius:999px;padding:7px 10px;color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.balance-copy{margin-top:36px}.balance-copy .mini-label{color:rgba(242,247,240,.52)}.balance-amount{font-family:'DM Mono',monospace;letter-spacing:-.075em;font-size:clamp(34px,4.5vw,58px);margin:10px 0 9px}.balance-caption{font-size:12px;color:var(--muted);max-width:360px;line-height:1.55}.stage-actions{display:flex;gap:8px;margin-top:26px}.plan-card{position:absolute;right:20px;bottom:20px;width:215px;padding:14px;border-radius:16px;background:rgba(7,11,9,.66);border:1px solid rgba(255,255,255,.11);backdrop-filter:blur(13px)}.plan-card h3{font-size:12px;margin:7px 0 4px;letter-spacing:-.03em}.plan-card p{font-size:10px;color:var(--muted);line-height:1.5;margin:0}.plan-icon{width:29px;height:29px;border-radius:10px;background:var(--lime-dim);display:grid;place-items:center;color:var(--acid)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.metric{padding:17px;border:1px solid var(--line);border-radius:17px;background:var(--ash)}.metric .value{font-family:'DM Mono',monospace;font-size:18px;letter-spacing:-.07em;margin:10px 0 6px}.metric p{font-size:10px;color:var(--muted);margin:0;line-height:1.45}.metric-line{margin-top:11px;height:4px;border-radius:99px;background:rgba(255,255,255,.06);overflow:hidden}.metric-line i{display:block;width:38%;height:100%;background:var(--acid);border-radius:99px}.side-stack{display:flex;flex-direction:column;gap:18px}.side-card{border:1px solid var(--line);border-radius:20px;background:var(--ash);padding:19px}.card-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.card-title{font-size:13px;font-weight:800;letter-spacing:-.035em}.text-btn{border:0;background:transparent;color:var(--acid);font-weight:800;font-size:11px;padding:0}.next-pay{display:flex;gap:11px;align-items:center;padding:12px 0;border-top:1px solid var(--line)}.next-pay:first-of-type{border-top:0;padding-top:0}.pay-icon{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:rgba(255,255,255,.05);color:var(--acid);flex:none}.pay-main{min-width:0;flex:1}.pay-main b{font-size:11px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pay-main span{font-size:10px;color:var(--muted);display:block;margin-top:3px}.pay-amount{font-family:'DM Mono',monospace;font-size:11px}.need-card{background:linear-gradient(145deg,rgba(255,181,76,.09),rgba(15,20,19,.97));border-color:rgba(255,181,76,.2)}.need-card .card-title{color:#ffd092}.attention-row{display:flex;gap:11px;align-items:center}.attention-icon{width:37px;height:37px;border-radius:12px;background:rgba(255,181,76,.15);display:grid;place-items:center;color:var(--amber);flex:none}.attention-row b{font-size:12px;display:block}.attention-row p{font-size:10px;color:var(--muted);line-height:1.45;margin:3px 0 0}.section{margin-top:30px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.section-head h2{font-size:15px;letter-spacing:-.04em;margin:0}.activity-list{border:1px solid var(--line);border-radius:20px;overflow:hidden;background:var(--ash)}.activity-row{display:grid;grid-template-columns:40px minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:15px 16px;border-bottom:1px solid var(--line);cursor:pointer;transition:background 160ms var(--ease)}.activity-row:last-child{border-bottom:0}.activity-row:hover{background:var(--panel-hi)}.merchant{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;color:#fff;font-weight:800;font-size:11px}.activity-copy{min-width:0;display:block}.activity-name{display:block;font-size:12px;font-weight:800;letter-spacing:-.02em}.activity-meta{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:6px}.activity-category{display:inline-flex;align-items:center;padding:3px 6px;border-radius:6px;background:rgba(255,255,255,.055);color:var(--text);font-size:9px;font-weight:700}.activity-time{font-size:10px;color:var(--muted)}.activity-amt{font-family:'DM Mono',monospace;font-size:12px;white-space:nowrap}.state{padding:5px 7px;border-radius:999px;font-size:9px;font-weight:800}.state.approved{color:var(--acid);background:var(--lime-dim)}.state.blocked{color:#ff9c9c;background:rgba(255,112,112,.11)}.state.review{color:#ffce8b;background:rgba(255,181,76,.12)}.receipt{padding:0 16px 15px;background:var(--panel);border-bottom:1px solid var(--line)}.receipt-inner{padding:13px 14px;border:1px solid var(--line);border-radius:14px;background:rgba(8,11,11,.5)}.receipt-title{display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:800}.receipt-reason{font-size:12px;line-height:1.55;margin:10px 0;color:var(--text)}.receipt-checks{display:flex;gap:6px;flex-wrap:wrap}.check{display:inline-flex;align-items:center;gap:4px;padding:5px 7px;border-radius:7px;background:var(--ash);border:1px solid var(--line);font-size:10px;color:var(--muted)}
/* Chat */
.assistant-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:18px}.chat-shell{height:calc(100vh - 158px);min-height:590px;display:flex;flex-direction:column;border:1px solid var(--line);border-radius:23px;overflow:hidden;background:var(--ash)}.chat-head{padding:17px 19px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:linear-gradient(90deg,rgba(76,242,166,.08),transparent)}.chat-agent{display:flex;gap:10px;align-items:center}.agent-orb{width:37px;height:37px;border-radius:50%;background:conic-gradient(from 210deg,var(--acid),var(--mint),#17553a,var(--acid));padding:2px;box-shadow:0 0 30px rgba(186,255,53,.14)}.agent-orb i{display:grid;place-items:center;width:100%;height:100%;border-radius:50%;background:#121a15}.chat-agent b{font-size:12px}.chat-agent span{font-size:10px;color:var(--acid);display:block;margin-top:2px}.model-pill{font-family:'DM Mono',monospace;font-size:9px;color:var(--muted);border:1px solid var(--line);padding:6px 8px;border-radius:9px}.chat-log{flex:1;overflow:auto;padding:25px;display:flex;flex-direction:column;gap:15px}.message{max-width:min(80%,620px);padding:12px 14px;border-radius:16px;font-size:12px;line-height:1.65}.message.user{align-self:flex-end;background:var(--acid);color:#11200d;border-bottom-right-radius:4px;font-weight:600}.message.nyra{align-self:flex-start;background:var(--panel-hi);border:1px solid var(--line);border-bottom-left-radius:4px}.message.notice{align-self:center;max-width:100%;padding:8px 12px;border-radius:10px;background:rgba(255,181,76,.09);border:1px solid rgba(255,181,76,.18);color:#eccb9b;font-size:10px}.suggestions{display:flex;gap:7px;flex-wrap:wrap;padding:0 18px 12px}.suggestion{background:rgba(255,255,255,.035);border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:10px;font-weight:700;padding:8px 10px}.composer{padding:13px 16px;border-top:1px solid var(--line);display:flex;align-items:flex-end;gap:9px;background:#101614}.composer textarea{min-height:42px;max-height:100px;resize:none;flex:1;background:transparent;border:0;color:var(--text);font-size:12px;line-height:1.5;padding:10px 4px}.composer textarea::placeholder{color:var(--soft)}.send-btn{width:41px;height:41px;display:grid;place-items:center;border:0;border-radius:13px;background:var(--acid);color:#14200c}.ai-sidebar{display:flex;flex-direction:column;gap:14px}.ai-card{border:1px solid var(--line);border-radius:18px;padding:17px;background:var(--ash)}.ai-card h3{font-size:13px;margin:0 0 7px}.ai-card p{font-size:11px;color:var(--muted);line-height:1.55;margin:0}.mode-line{display:flex;align-items:center;gap:9px;padding:11px 0;border-top:1px solid var(--line);font-size:11px}.mode-line:first-of-type{border-top:0;padding-top:0}.mode-line svg{color:var(--acid)}
/* Controls */
.controls-wrap{max-width:900px}.permission-hero{border:1px solid rgba(186,255,53,.18);border-radius:23px;padding:24px;background:linear-gradient(130deg,rgba(76,242,166,.11),rgba(15,20,19,.94) 54%);margin-bottom:18px}.permission-hero h2{font-family:'Instrument Serif',Georgia,serif;font-size:37px;font-weight:400;letter-spacing:-.05em;margin:7px 0 8px}.permission-hero p{font-size:12px;line-height:1.65;color:var(--muted);max-width:570px;margin:0}.permission-legend{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:21px}.legend-card{padding:12px;border:1px solid var(--line);border-radius:13px;background:rgba(8,11,11,.28)}.legend-card b{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:5px}.legend-card span{display:block;font-size:10px;line-height:1.5;color:var(--muted)}.legend-card.auto b{color:var(--acid)}.legend-card.ask b{color:var(--amber)}.legend-card.never b{color:var(--rose)}.control-section{border:1px solid var(--line);border-radius:19px;background:var(--ash);padding:20px;margin-bottom:14px}.control-title{font-size:14px;font-weight:800;letter-spacing:-.04em;margin-bottom:4px}.control-sub{font-size:11px;color:var(--muted);line-height:1.55;margin-bottom:16px}.limit-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{padding:13px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.field label{display:block;font-size:9px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;color:var(--soft);margin-bottom:8px}.field input{width:100%;border:0;background:transparent;color:var(--text);font-family:'DM Mono',monospace;font-size:17px;outline:0}.permission-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:center;padding:15px 0;border-top:1px solid var(--line)}.permission-row:first-child{border-top:0;padding-top:0}.permission-row b{display:block;font-size:12px;text-transform:capitalize}.permission-row span{display:block;margin-top:3px;font-size:10px;color:var(--muted)}.segmented{display:flex;border:1px solid var(--line);border-radius:11px;padding:3px;background:#101513}.seg{background:transparent;border:0;border-radius:8px;color:var(--soft);font-size:10px;font-weight:800;padding:7px 9px}.seg.auto.on{background:var(--lime-dim);color:var(--acid)}.seg.ask.on{background:rgba(255,181,76,.13);color:#ffc16c}.seg.never.on{background:rgba(255,112,112,.12);color:#ff9c9c}.danger-row{display:flex;align-items:center;gap:12px;padding:14px;border-radius:14px;background:rgba(255,112,112,.06);border:1px solid rgba(255,112,112,.14)}.danger-row p{font-size:10px;line-height:1.5;color:var(--muted);margin:3px 0 0}.toggle{position:relative;width:44px;height:25px;border:0;border-radius:99px;background:#38413d;margin-left:auto}.toggle i{position:absolute;width:19px;height:19px;border-radius:50%;background:#d7e0d5;left:3px;top:3px;transition:transform 180ms var(--ease)}.toggle.on{background:var(--acid)}.toggle.on i{transform:translateX(19px);background:#13200d}
.module-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.feature-panel{border:1px solid var(--line);border-radius:20px;background:var(--ash);padding:19px}.feature-panel h2{font-size:16px;letter-spacing:-.04em;margin:0}.feature-panel p{font-size:11px;color:var(--muted);line-height:1.55;margin:7px 0 0}.module-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:16px}.module-icon{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--lime-dim);color:var(--acid);flex:none}.goal-list,.event-list{display:grid;gap:9px}.goal-row,.event-row{border:1px solid var(--line);border-radius:14px;padding:13px;background:rgba(255,255,255,.018)}.goal-row{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:10px;align-items:center}.goal-row b,.event-row b{font-size:11px;display:block}.goal-row span,.event-row span{font-size:10px;color:var(--muted);display:block;margin-top:3px}.goal-progress{height:5px;background:rgba(255,255,255,.07);border-radius:99px;overflow:hidden;margin-top:9px}.goal-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--mint),var(--acid));border-radius:99px}.send-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px}.send-form{border:1px solid var(--line);border-radius:22px;background:var(--ash);padding:22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.input-field{display:block;border:1px solid var(--line);border-radius:13px;padding:12px;background:var(--panel);color:var(--soft);font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.input-field.full{grid-column:1/-1}.input-field input,.input-field select{width:100%;border:0;outline:0;background:transparent;color:var(--text);font-size:13px;font-weight:600;margin-top:8px;text-transform:none;letter-spacing:0}.draft-card{border:1px solid rgba(186,255,53,.18);border-radius:18px;padding:17px;background:linear-gradient(145deg,rgba(186,255,53,.07),rgba(255,255,255,.02))}.draft-amount{font:24px 'DM Mono',monospace;letter-spacing:-.07em;margin:7px 0}.draft-meta{display:flex;flex-wrap:wrap;gap:6px}.draft-meta span{font-size:9px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;color:var(--muted)}.result-banner{padding:13px 15px;border-radius:13px;margin-top:14px;font-size:11px;line-height:1.5}.result-banner.ok{background:var(--lime-dim);border:1px solid rgba(186,255,53,.2);color:var(--acid)}.result-banner.warn{background:rgba(255,181,76,.1);border:1px solid rgba(255,181,76,.2);color:#ffd092}.result-banner.stop{background:rgba(255,112,112,.1);border:1px solid rgba(255,112,112,.2);color:#ffaaaa}.campus-strip{display:flex;gap:8px;overflow:auto;margin-top:14px;padding-bottom:3px}.campus-chip{white-space:nowrap;border:1px solid var(--line);background:var(--panel);border-radius:999px;padding:8px 10px;color:var(--muted);font-size:10px}.campus-chip b{color:var(--text);margin-right:4px}.module-kicker{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:var(--acid);text-transform:uppercase}.stat-pair{display:flex;justify-content:space-between;align-items:end;margin:14px 0}.stat-pair strong{font:24px 'DM Mono',monospace;letter-spacing:-.07em}.stat-pair span{font-size:10px;color:var(--muted)}
/* mobile */
.mobile-dock{display:none}@media(max-width:900px){.rail{display:none}.module-grid{grid-template-columns:1fr}.send-layout{grid-template-columns:1fr}.app-main{margin-left:0;width:100%}.topbar{height:72px;padding:0 18px}.topbar .page-title p{display:none}.content{padding:18px 18px 98px}.home-grid,.assistant-layout{grid-template-columns:1fr}.side-stack{display:grid;grid-template-columns:1fr 1fr}.chat-shell{height:calc(100vh - 170px);min-height:500px}.ai-sidebar{display:none}.mobile-dock{height:67px;display:flex;align-items:center;justify-content:space-around;position:fixed;left:0;right:0;bottom:0;padding:0 9px calc(env(safe-area-inset-bottom, 0px) + 5px);background:rgba(10,14,13,.96);border-top:1px solid var(--line);backdrop-filter:blur(18px);z-index:40}.dock-item{border:0;background:transparent;color:var(--soft);padding:7px 10px;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:9px;font-weight:800}.dock-item.active{color:var(--acid)}.dock-item.active svg{filter:drop-shadow(0 0 7px rgba(186,255,53,.45))}.landing-main{padding:62px 24px 38px;grid-template-columns:1fr;gap:35px}.hero h1{font-size:66px;max-width:490px}.hero-art{min-height:388px}.money-orbit{width:350px;right:-20px}.hero-card.main{width:min(320px,90%);right:0;top:50px}.hero-card.small{width:205px;bottom:0}.landing-detail{grid-template-columns:1fr;padding:10px 20px 52px}.detail-intro{padding:20px 0 8px}.detail-intro h2{font-size:47px}.pulse-board{min-height:270px}.landing-footer{padding:0 20px 98px;grid-template-columns:1fr}.landing-nav{padding:0 20px}.nav-link{display:none}.permission-legend{grid-template-columns:1fr}.permission-hero h2{font-size:32px}}
@media(max-width:560px){.topbar{padding:0 16px}.top-actions .icon-btn{display:none}.content{padding:16px 14px 96px}.balance-stage{min-height:350px;padding:20px;border-radius:20px}.balance-copy{margin-top:28px}.balance-amount{font-size:33px;white-space:nowrap}.stage-actions .btn{flex:1;padding:12px 8px;font-size:11px}.plan-card{position:relative;right:auto;bottom:auto;width:100%;margin-top:18px}.metrics{grid-template-columns:1fr 1fr}.metric:first-child{grid-column:span 2}.metric{padding:14px}.metric .value{font-size:17px}.side-stack{grid-template-columns:1fr;gap:12px}.section{margin-top:23px}.activity-row{grid-template-columns:38px minmax(0,1fr) auto;gap:10px;padding:15px 13px}.activity-row .state{display:none}.activity-meta{max-width:205px}.activity-category{font-size:9px}.activity-time{font-size:9px}.activity-amt{font-size:11px}.receipt{padding:0 12px 12px}.permission-hero{padding:19px}.control-section{padding:17px}.limit-grid{grid-template-columns:1fr}.permission-row{grid-template-columns:1fr;gap:11px}.segmented{width:100%}.seg{flex:1}.message{max-width:92%}.chat-log{padding:17px}.suggestions{padding:0 12px 10px}.landing-main{padding:54px 20px 32px}.hero h1{font-size:57px}.hero-copy{font-size:14px}.hero-cta{display:grid;grid-template-columns:1fr}.hero-cta .btn{width:100%}.hero-art{min-height:350px}.hero-card.main{padding:17px}.mini-money{font-size:22px}.pulse-bars{gap:6px}.pulse-tags{gap:5px}.pulse-tag{font-size:9px;padding:6px 7px}.landing-nav .btn{padding:9px 12px}.landing-footer{padding:0 20px 92px}.brand-mark{width:31px;height:31px}.logo{font-size:16px}}
`;

