function NLogo({ size = 24 }) {
  return <svg width={size} height={size} viewBox="0 0 40 40" fill="none" aria-hidden="true"><defs><linearGradient id="nyra-gradient" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse"><stop stopColor="#4CF2A6"/><stop offset="1" stopColor="#BAFF35"/></linearGradient></defs><path d="M7 33V7l26 26V7" stroke="url(#nyra-gradient)" strokeWidth="3.2" strokeLinecap="round" strokeLinejoin="round"/><circle cx="20" cy="20" r="3" fill="#BAFF35"/></svg>;
}

function Logo() { return <div className="logo"><span className="brand-mark"><NLogo size={21}/></span><span>nyra</span></div>; }
function money(value) { return `₦${Number(value).toLocaleString("en-NG")}`; }

function Landing({ onStart }) {
  return <div className="landing"><nav className="landing-nav"><Logo/><div style={{display:"flex",gap:10,alignItems:"center"}}><button className="nav-link" onClick={onStart}>Sign in</button><button className="btn btn-acid btn-sm" onClick={onStart}>Get started <ArrowUpRight size={14}/></button></div></nav><main className="landing-main"><section className="hero"><span className="eyebrow"><Sparkles size={13}/>The money co-pilot</span><h1>Let money move <em>with intent.</em></h1><p className="hero-copy">Nyra handles the routine, watches the rules, and brings you in only when judgment matters. A calmer way to stay ahead of your money.</p><div className="hero-cta"><button className="btn btn-acid" onClick={onStart}>Build your money rules <ArrowUpRight size={15}/></button><button className="btn btn-quiet" onClick={onStart}>See how Nyra thinks</button></div><p className="hero-note">No silent payments. Every decision leaves a clear trail.</p></section><section className="hero-art" aria-label="Nyra product preview"><div className="money-orbit"/><div className="hero-card main"><div className="mini-label">Money available</div><div className="mini-money">₦1,250,000</div><div className="track"><i/></div><div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:"var(--muted)",marginTop:8}}><span>36% of your monthly plan</span><span>On track</span></div><div style={{marginTop:20}}><div className="hero-chip"><span className="avatar-dot"><Zap size={14}/></span><span style={{flex:1}}>Electricity bill is ready</span><ChevronRight size={15} color="var(--soft)"/></div><div className="hero-chip"><span className="avatar-dot"><ShieldCheck size={14}/></span><span style={{flex:1}}>One transfer needs you</span><span style={{color:"var(--amber)",fontSize:10}}>Review</span></div></div></div><div className="hero-card small"><div className="trust-line"><LockKeyhole size={15}/><span>Autonomy, with boundaries.</span></div><p style={{color:"var(--text)",fontSize:13,fontWeight:800,lineHeight:1.45,margin:"11px 0 0"}}>Nyra follows your rules, not its own.</p></div></section></main><section className="landing-detail"><div className="detail-intro"><span className="eyebrow"><Sparkles size={13}/>A money rhythm, not a money maze</span><h2>See the shape of your week before it gets busy.</h2><p>Nyra turns the small, repeated decisions into a simple pulse: what is moving, what is safe to handle, and what needs your voice.</p></div><div className="pulse-board"><div className="pulse-head"><div><span className="pulse-kicker">YOUR WEEKLY MONEY PULSE</span><b>Quietly handled, clearly visible.</b></div><span className="pulse-stamp">19—25 AUG</span></div><div className="pulse-bars"><i className="pulse-bar dim" style={{height:"32%"}}/><i className="pulse-bar" style={{height:"52%"}}/><i className="pulse-bar" style={{height:"43%"}}/><i className="pulse-bar" style={{height:"76%"}}/><i className="pulse-bar" style={{height:"61%"}}/><i className="pulse-bar" style={{height:"88%"}}/><i className="pulse-bar dim" style={{height:"39%"}}/></div><div className="pulse-labels"><span>MON</span><span>WED</span><span>FRI</span><span>SUN</span></div><div className="pulse-tags"><span className="pulse-tag"><strong>03</strong> bills ahead</span><span className="pulse-tag"><strong>02</strong> subscriptions</span><span className="pulse-tag"><strong>01</strong> needs you</span></div></div></section><section className="landing-footer"><article className="principle"><span className="principle-index">01 · BOUNDARIES</span><b>Built around permissions</b><p>Choose what Nyra can handle, what needs a check-in, and what never moves without you.</p></article><article className="principle"><span className="principle-index">02 · RECEIPTS</span><b>Every decision is legible</b><p>See the policy, recipient, amount, and reason behind every approved or stopped payment.</p></article><article className="principle"><span className="principle-index">03 · RHYTHM</span><b>Made for real life</b><p>Bills, transfers, subscriptions, and unexpected moments—all in one clear rhythm.</p></article></section></div>;
}

function Login({ onContinue }) {
  return <div className="landing" style={{display:"grid",placeItems:"center",padding:20}}><div style={{width:"min(430px,100%)",padding:28,border:"1px solid var(--line)",borderRadius:24,background:"var(--ash)",boxShadow:"0 28px 90px rgba(0,0,0,.32)"}}><Logo/><span className="eyebrow" style={{marginTop:40}}>Welcome to Nyra</span><h1 style={{fontFamily:"'Instrument Serif',Georgia,serif",fontSize:45,fontWeight:400,letterSpacing:"-.05em",lineHeight:.93,margin:"12px 0"}}>Start with the rules. <i style={{color:"var(--acid)"}}>Then relax.</i></h1><p style={{fontSize:12,lineHeight:1.65,color:"var(--muted)",marginBottom:24}}>This prototype opens a sample workspace. Your identity and account details stay dynamic in a production connection.</p><button className="btn btn-acid btn-full" onClick={onContinue}>Open sample workspace <ArrowUpRight size={15}/></button></div></div>;
}

function Rail({ page, setPage, reviewCount }) {
  const links = [["home",Home,"Home"],["send",Send,"Send money"],["savings",CircleDollarSign,"Savings"],["campus",FileText,"Campus plan"],["activity",ReceiptText,"Activity"],["assistant",MessageCircle,"Ask Nyra"],["controls",Settings2,"Your controls"]];
  return <aside className="rail"><Logo/><nav className="nav-group">{links.map(([id,Icon,label])=><button key={id} className={`nav-item ${page===id?"active":""}`} onClick={()=>setPage(id)}><Icon size={17}/>{label}{id==="assistant"&&reviewCount>0?<span className="counter">{reviewCount}</span>:null}</button>)}</nav><div className="rail-foot"><div className="agent-status"><span className="pulse"/>NYRA IS ON</div><p>Watching approved categories and waiting for your lead on exceptions.</p></div></aside>;
}

function Topbar({ page, setPage }) {
  const title = {home:["Your money, in rhythm.","Monday, 19 August"],send:["Move money with intent.","Draft, review, and send from one place"],savings:["Your goals, in motion.","Nyra keeps your plans moving"],campus:["Campus plan.","Obligations, contributions, and what is next"],activity:["Everything Nyra did.","A clear record of every decision"],assistant:["Ask Nyra.","Your money co-pilot, on call"],controls:["Set the boundaries.","Decide exactly what Nyra may do"]}[page];
  return <header className="topbar"><div className="page-title"><h1>{title[0]}</h1><p>{title[1]}</p></div><div className="top-actions"><button className="icon-btn" aria-label="Notifications"><Bell size={17}/><span className="notify-dot"/></button><button className="profile-button" aria-label="Account" onClick={()=>setPage("controls")}>N</button></div></header>;
}

function Status({ status }) { const labels={approved:"Approved",blocked:"Blocked",review:"Review"}; return <span className={`state ${status}`}>{labels[status]}</span>; }

function DecisionReceipt({ transaction, onControls }) {
  const isReview=transaction.status==="review"; const isBlocked=transaction.status==="blocked";
  const checks=isReview?["New recipient","Awaiting you"]:isBlocked?["Limit checked","Payment stopped"]:["Within limit","Trusted recipient","Allowed category"];
  return <div className="receipt"><div className="receipt-inner"><div className="receipt-title"><span>Decision record</span><Status status={transaction.status}/></div><p className="receipt-reason">{transaction.reason}</p><div className="receipt-checks">{checks.map((check,index)=><span className="check" key={check}>{index===0?<ShieldCheck size={11} color="var(--acid)"/>:<Sparkles size={10} color={isReview?"var(--amber)":isBlocked?"var(--rose)":"var(--acid)"}/>} {check}</span>)}</div>{(isReview||isBlocked)&&<button className="text-btn" style={{marginTop:12}} onClick={onControls}>{isReview?"Review your transfer rules →":"Change your payment limit →"}</button>}</div></div>;
}

function HomePage({ setPage, policy, onTogglePause, wallet, transactions }) {
  const [openId,setOpenId]=useState(null); const review=transactions.find(t=>t.status==="review") || TRANSACTIONS.find(t=>t.status==="review");
  return <div className="home-grid"><main><section className="balance-stage"><div className="stage-head"><span className="active-pill"><span className="pulse"/>Nyra is active</span><button className="icon-btn" aria-label="More actions"><MoreHorizontal size={17}/></button></div><div className="balance-copy"><span className="mini-label">Available to move</span><div className="balance-amount">{money(wallet.available)}<span style={{fontSize:".42em",color:"var(--muted)"}}>.00</span></div><p className="balance-caption">After your active plan and scheduled payments, this is what Nyra sees as available.</p></div><div className="stage-actions"><button className="btn btn-acid" onClick={()=>setPage("assistant")}>Ask Nyra <Sparkles size={14}/></button><button className="btn btn-outline" onClick={onTogglePause}><Pause size={14}/>Pause</button></div><article className="plan-card"><span className="plan-icon"><Zap size={15}/></span><h3>One thing ahead</h3><p>IKEDC electricity is ready to pay Friday—inside your utility rule.</p></article></section><section className="metrics"><article className="metric"><span className="mini-label">This month</span><div className="value">₦356,800</div><p>36% of your ₦1M comfort ceiling</p><div className="metric-line"><i/></div></article><article className="metric"><span className="mini-label">Auto-handled</span><div className="value">42</div><p>Payments checked against your rules</p></article><article className="metric"><span className="mini-label">Savings pace</span><div className="value">78%</div><p>of your emergency buffer goal</p></article></section><section className="section"><div className="section-head"><h2>Recent decisions</h2><button className="text-btn" onClick={()=>setPage("activity")}>See all activity</button></div><div className="activity-list">{transactions.slice(0,5).map(t=><div key={t.id}>{<div className="activity-row" onClick={()=>setOpenId(openId===t.id?null:t.id)}><span className="merchant" style={{background:t.color}}>{t.initial}</span><span className="activity-copy"><span className="activity-name">{t.name}</span><span className="activity-meta"><span className="activity-category">{t.category}</span><span className="activity-time">{t.time}</span></span></span><span className="activity-amt">{money(t.amount)}</span><Status status={t.status}/></div>}{openId===t.id&&<DecisionReceipt transaction={t} onControls={()=>setPage("controls")}/>}</div>)}</div></section></main><aside className="side-stack"><section className="side-card"><div className="card-head"><span className="card-title">Coming up</span><button className="text-btn">Calendar</button></div><div className="next-pay"><span className="pay-icon"><Zap size={16}/></span><span className="pay-main"><b>IKEDC electricity</b><span>Friday · Auto-pay</span></span><span className="pay-amount">₦4,500</span></div><div className="next-pay"><span className="pay-icon"><CreditCard size={16}/></span><span className="pay-main"><b>Spotify</b><span>28 Aug · Auto-pay</span></span><span className="pay-amount">₦1,500</span></div></section><section className="side-card need-card"><div className="card-head"><span className="card-title">Requires you</span><span style={{color:"var(--amber)",fontSize:10,fontWeight:800}}>1 item</span></div><div className="attention-row"><span className="attention-icon"><ShieldCheck size={17}/></span><span><b>{review.name} · {money(review.amount)}</b><p>New recipient. Nyra will wait until you decide.</p></span></div><button className="btn btn-quiet btn-full btn-sm" style={{marginTop:15}} onClick={()=>setPage("activity")}>Review payment <ChevronRight size={14}/></button></section><section className="side-card"><div className="card-head"><span className="card-title">Your boundaries</span><button className="text-btn" onClick={()=>setPage("controls")}>Edit</button></div><div style={{display:"grid",gap:9}}><div className="trust-line"><ShieldCheck size={15}/><span>Auto-pay below {money(policy.perPayment)}</span></div><div className="trust-line"><MessageCircle size={15}/><span>Ask first for new recipients</span></div><div className="trust-line"><LockKeyhole size={15}/><span>Stop at your monthly limit</span></div></div></section></aside></div>;
}

function ActivityPage({ setPage, transactions = TRANSACTIONS }) {
  const [filter,setFilter]=useState("all"); const [openId,setOpenId]=useState(null); const list=filter==="all"?transactions:transactions.filter(t=>t.status===filter);
  return <section><div className="section-head" style={{marginTop:0}}><div><h2>Decision history</h2><p style={{fontSize:11,color:"var(--muted)",margin:"4px 0 0"}}>Not just a transaction list—this is Nyra’s accountability trail.</p></div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{[["all","All"],["approved","Approved"],["review","Needs review"],["blocked","Stopped"]].map(([id,label])=><button key={id} className={`btn btn-sm ${filter===id?"btn-acid":"btn-quiet"}`} onClick={()=>setFilter(id)}>{label}</button>)}</div></div><div className="activity-list">{list.map(t=><div key={t.id}><div className="activity-row" onClick={()=>setOpenId(openId===t.id?null:t.id)}><span className="merchant" style={{background:t.color}}>{t.initial}</span><span className="activity-copy"><span className="activity-name">{t.name}</span><span className="activity-meta"><span className="activity-category">{t.category}</span><span className="activity-time">{t.time}</span></span></span><span className="activity-amt">{money(t.amount)}</span><Status status={t.status}/></div>{openId===t.id&&<DecisionReceipt transaction={t} onControls={()=>setPage("controls")}/>}</div>)}</div></section>;
}

function SavingsPage({ wallet, setWallet, transactions, setTransactions }) {
  const [goals,setGoals]=useState(INITIAL_GOALS); const [notice,setNotice]=useState("");
  const contribute=(goal)=>{const amount=Math.min(10000,wallet.available);if(amount<=0){setNotice("Nyra cannot move money into a goal while the available balance is empty.");return;}setWallet(current=>({...current,available:current.available-amount,reserved:current.reserved+amount}));setGoals(current=>current.map(item=>item.id===goal.id?{...item,saved:item.saved+amount}:item));setTransactions(current=>[{id:Date.now(),name:goal.name,category:"Savings goal",time:"Just now",amount,status:"approved",color:"#4cf2a6",initial:"G",reason:`₦${amount.toLocaleString("en-NG")} moved into your ${goal.name} goal.`},...current]);setNotice(`Nyra moved ${money(amount)} into ${goal.name}.`);};
  return <section><div className="module-head"><div><span className="module-kicker">Savings studio</span><h2 style={{fontFamily:"'Instrument Serif',Georgia,serif",fontSize:38,fontWeight:400,margin:"7px 0 0"}}>Give your next plan somewhere to go.</h2><p style={{maxWidth:570}}>Nyra can move a comfortable amount into your goals while keeping your campus commitments visible.</p></div><span className="module-icon"><CircleDollarSign size={18}/></span></div><div className="module-grid">{goals.map(goal=>{const progress=Math.min(100,Math.round(goal.saved/goal.target*100));return <article className="feature-panel" key={goal.id}><div className="module-head" style={{marginBottom:10}}><span className="module-icon" style={{background:`${goal.color}18`,color:goal.color}}><Sparkles size={15}/></span><span className="module-kicker">{goal.due}</span></div><h2>{goal.name}</h2><div className="stat-pair"><strong>{money(goal.saved)}</strong><span>of {money(goal.target)}</span></div><div className="goal-progress"><i style={{width:`${progress}%`,background:goal.color}}/></div><p>{progress}% funded. Nyra suggests a {money(10000)} contribution when your upcoming commitments are covered.</p><button className="btn btn-quiet btn-sm" style={{marginTop:14}} onClick={()=>contribute(goal)}>Move {money(10000)} <ArrowUpRight size={13}/></button></article>})}</div>{notice&&<div className="result-banner ok">{notice}</div>}</section>;
}

function CampusPage({ setPage }) { return <section><div className="module-head"><div><span className="module-kicker">Campus plan</span><h2 style={{fontFamily:"'Instrument Serif',Georgia,serif",fontSize:38,fontWeight:400,margin:"7px 0 0"}}>Everything due, without the mental load.</h2><p style={{maxWidth:570}}>Nyra keeps school obligations and everyday commitments in one money-aware plan.</p></div><span className="module-icon"><FileText size={18}/></span></div><div className="feature-panel"><div className="card-head"><span className="card-title">Coming up</span><button className="text-btn" onClick={()=>setPage("savings")}>Open savings</button></div><div className="event-list">{CAMPUS_EVENTS.map(event=>{const Icon=event.icon;return <div className="event-row" key={event.id} style={{display:"flex",alignItems:"center",gap:11}}><span className="module-icon"><Icon size={15}/></span><span style={{flex:1}}><b>{event.title}</b><span>{event.kind} · {event.date}</span></span><strong style={{fontFamily:"'DM Mono',monospace",fontSize:11}}>{money(event.amount)}</strong></div>})}</div><div className="campus-strip"><span className="campus-chip"><b>3</b> obligations ahead</span><span className="campus-chip"><b>₦199,500</b> planned</span><span className="campus-chip"><b>1</b> needs review</span></div></div><div className="module-grid" style={{marginTop:14}}><article className="feature-panel"><span className="module-kicker">Shared money</span><h2 style={{marginTop:8}}>Project printing</h2><p>6 contributors · ₦60,000 target · 4 paid</p><button className="btn btn-quiet btn-sm" style={{marginTop:14}}>View contribution</button></article><article className="feature-panel"><span className="module-kicker">Money rhythm</span><h2 style={{marginTop:8}}>This week</h2><p>Utilities, data, transport, and one savings contribution are all visible.</p><button className="btn btn-acid btn-sm" style={{marginTop:14}} onClick={()=>setPage("assistant")}>Ask Nyra <Sparkles size={13}/></button></article></div></section>; }

function SendPage({ wallet, setWallet, transactions, setTransactions, policy }) {
  const [recipient,setRecipient]=useState("Tunde Adeola"); const [amount,setAmount]=useState("20000"); const [category,setCategory]=useState("transfer"); const [note,setNote]=useState("Campus expense"); const [pending,setPending]=useState(null); const [result,setResult]=useState(null);
  const categoryKey=category==="utility"?"utilities":category==="subscription"?"subscriptions":category==="shopping"?"shopping":"transfers";
  const evaluate=(force=false)=>{const value=Number(amount);const trusted=policy.trusted.some(name=>recipient.toLowerCase().includes(name.toLowerCase()));const preference=policy.categories[categoryKey]||"ask";if(!recipient.trim()||!value||value<1){setResult({kind:"stop",text:"Add a valid recipient and amount before Nyra can prepare this transfer."});return;}if(policy.paused){setResult({kind:"stop",text:"Nyra is paused. Turn the agent back on before sending money."});return;}if(value>wallet.available){setResult({kind:"stop",text:`This transfer is above the available balance of ${money(wallet.available)}.`});return;}if(preference==="never"||value>policy.perPayment||wallet.monthlySpent+value>policy.monthlyLimit){setResult({kind:"stop",text:"Nyra stopped this request because it falls outside the current money preferences."});return;}if(!force&&(preference==="ask"||(!trusted&&policy.firstTime))){setPending({recipient,amount:value,category,note});setResult({kind:"warn",text:"Nyra prepared the transfer but is waiting for your confirmation because the recipient or amount needs your attention."});return;}const tx={id:Date.now(),name:recipient,category:category,time:"Just now",amount:value,status:"approved",color:"#2563eb",initial:recipient.trim()[0].toUpperCase(),reason:`Sent because this request matched your ${preference} preference and the available balance was sufficient.`};setWallet(current=>({...current,available:current.available-value,monthlySpent:current.monthlySpent+value}));setTransactions(current=>[tx,...current]);setPending(null);setResult({kind:"ok",text:`Nyra sent ${money(value)} to ${recipient}. A decision receipt was added to Activity.`});};
  return <section className="send-layout"><div className="send-form"><div className="module-head"><div><span className="module-kicker">Autonomous transfer</span><h2 style={{fontFamily:"'Instrument Serif',Georgia,serif",fontSize:38,fontWeight:400,margin:"7px 0 0"}}>Move money with context.</h2><p>Draft a transfer. Nyra checks your balance, category preference, recipient history, and campus plan before acting.</p></div><span className="module-icon"><Send size={17}/></span></div><div className="form-grid"><label className="input-field full">Recipient<input value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder="Name or wallet recipient"/></label><label className="input-field">Amount<input type="number" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label className="input-field">Category<select value={category} onChange={e=>setCategory(e.target.value)}><option value="transfer">Transfer</option><option value="utility">Utility</option><option value="subscription">Subscription</option><option value="shopping">Shopping</option></select></label><label className="input-field full">Note<input value={note} onChange={e=>setNote(e.target.value)} placeholder="What is this for?"/></label></div>{result&&<div className={`result-banner ${result.kind}`}>{result.text}</div>}{pending&&<div className="draft-card" style={{marginTop:14}}><span className="module-kicker">Review before sending</span><div className="draft-amount">{money(pending.amount)}</div><div className="draft-meta"><span>{pending.recipient}</span><span>{pending.category}</span><span>{pending.note}</span></div><button className="btn btn-acid btn-sm" style={{marginTop:14}} onClick={()=>evaluate(true)}>Confirm and send <ArrowUpRight size={13}/></button></div>}<button className="btn btn-acid" style={{marginTop:16}} onClick={()=>evaluate(false)}>{pending?"Prepare another transfer":"Ask Nyra to review"}<ArrowUpRight size={15}/></button></div><aside className="feature-panel"><div className="module-head"><div><span className="module-kicker">Today</span><h2>Wallet context</h2></div><span className="module-icon"><WalletCards size={16}/></span></div><div className="stat-pair"><strong>{money(wallet.available)}</strong><span>available</span></div><div className="goal-progress"><i style={{width:`${Math.min(100,wallet.monthlySpent/policy.monthlyLimit*100)}%`}}/></div><p>{money(wallet.monthlySpent)} used this month. Nyra keeps your planned campus commitments in view before it acts.</p><div className="campus-strip"><span className="campus-chip"><b>{transactions.filter(t=>t.status==="review").length}</b> needs review</span><span className="campus-chip"><b>{transactions.length}</b> decisions</span></div></aside></section>;
}

function AssistantPage({ policy }) {
  const [messages,setMessages]=useState([{role:"nyra",content:"I’m Nyra. I can explain your money activity, draft a payment plan, and help you adjust your rules. I won’t move money from a chat message."}]);
  const [input,setInput]=useState(""); const [loading,setLoading]=useState(false); const endRef=useRef(null);
  useEffect(()=>endRef.current?.scrollIntoView({behavior:"smooth"}),[messages,loading]);
  const send=async(text=input)=>{const value=text.trim();if(!value||loading)return;setInput("");setMessages(prev=>[...prev,{role:"user",content:value}]);setLoading(true);try{const response=await fetch("/api/ai/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:[...messages.filter(m=>m.role!=="notice"),{role:"user",content:value}],policy})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Nyra is unavailable right now.");setMessages(prev=>[...prev,{role:"nyra",content:data.content,model:data.model}]);}catch(error){setMessages(prev=>[...prev,{role:"notice",content:error.message.includes("not configured")?"Nyra is ready for its live connection. Add the server-side AI settings, then redeploy.":"Nyra could not reach the assistant service. Check the server settings and try again."}]);}finally{setLoading(false)}};
  return <div className="assistant-layout"><section className="chat-shell"><header className="chat-head"><div className="chat-agent"><span className="agent-orb"><i><NLogo size={16}/></i></span><span><b>Nyra assistant</b><span>Private · rule-aware · no direct execution</span></span></div><span className="model-pill">NYRA / READY</span></header><div className="chat-log">{messages.map((message,index)=><div key={index} className={`message ${message.role}`}>{message.content}</div>)}{loading&&<div className="message nyra">Nyra is checking the context…</div>}<div ref={endRef}/></div><div className="suggestions">{["Why did Nyra stop my last payment?","Help me tighten my spending rules","What bills are coming up?"].map(prompt=><button className="suggestion" key={prompt} onClick={()=>send(prompt)}>{prompt}</button>)}</div><form className="composer" onSubmit={event=>{event.preventDefault();send()}}><textarea value={input} onChange={event=>setInput(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();send()}}} placeholder="Ask about a payment, rule, or money plan…"/><button className="send-btn" aria-label="Send message" disabled={!input.trim()||loading}><Send size={17}/></button></form></section><aside className="ai-sidebar"><section className="ai-card"><h3>How Nyra behaves</h3><p>Your assistant explains and drafts. Rules and explicit approvals remain the source of truth for money movement.</p></section><section className="ai-card"><h3>What it can help with</h3><div className="mode-line"><ReceiptText size={15}/><span>Explain an activity decision</span></div><div className="mode-line"><WalletCards size={15}/><span>Plan upcoming bills</span></div><div className="mode-line"><Settings2 size={15}/><span>Suggest clearer boundaries</span></div></section><section className="ai-card"><h3>Private by design</h3><p>Your assistant connection stays behind the app. The browser never needs to know how the service is configured.</p></section></aside></div>;
}

function ControlsPage({ policy, setPolicy }) {
  const [draft,setDraft]=useState(policy); const [saved,setSaved]=useState(false); const updateCategory=(category,value)=>setDraft(current=>({...current,categories:{...current.categories,[category]:value}})); const save=()=>{setPolicy(draft);setSaved(true);setTimeout(()=>setSaved(false),1800)};
  const desc={auto:"Nyra may handle this inside your limits.",ask:"Nyra must wait for you.",never:"Nyra will not handle this."};
  return <div className="controls-wrap"><section className="permission-hero"><span className="eyebrow"><ShieldCheck size={13}/>Your money boundaries</span><h2>Autonomy is a permission, not a surprise.</h2><p>Choose the moments Nyra can handle quietly, the moments that need you, and the ones it must never touch. You can revise these rules whenever life changes.</p><div className="permission-legend"><div className="legend-card auto"><b>Auto-pay</b><span>Routine, permitted, inside your limits.</span></div><div className="legend-card ask"><b>Ask first</b><span>Anything that deserves your judgment.</span></div><div className="legend-card never"><b>Never</b><span>Out of bounds, every time.</span></div></div></section><section className="control-section"><div className="control-title">Set the ceiling</div><p className="control-sub">Nyra pauses and asks when a payment would go beyond either number.</p><div className="limit-grid"><label className="field"><span>Per payment</span><input aria-label="Per payment limit" type="number" value={draft.perPayment} onChange={e=>setDraft({...draft,perPayment:Number(e.target.value)})}/></label><label className="field"><span>Monthly comfort ceiling</span><input aria-label="Monthly limit" type="number" value={draft.monthlyLimit} onChange={e=>setDraft({...draft,monthlyLimit:Number(e.target.value)})}/></label></div></section><section className="control-section"><div className="control-title">Choose what Nyra can touch</div><p className="control-sub">Make a direct decision for each category. These are visible in every decision record.</p>{Object.entries(draft.categories).map(([category,value])=><div className="permission-row" key={category}><span><b>{category}</b><span>{desc[value]}</span></span><div className="segmented">{[["auto","Auto"],["ask","Ask"],["never","Never"]].map(([id,label])=><button className={`seg ${id} ${value===id?"on":""}`} key={id} onClick={()=>updateCategory(category,id)}>{label}</button>)}</div></div>)}</section><section className="control-section"><div className="control-title">Your safety net</div><p className="control-sub">New recipients are always worth a second look.</p><div className="danger-row"><span style={{color:"var(--rose)"}}><LockKeyhole size={19}/></span><span><b style={{fontSize:12}}>Pause Nyra immediately</b><p>Stop it from initiating any new automatic payment until you turn it back on.</p></span><button aria-label="Pause Nyra" className={`toggle ${draft.paused?"on":""}`} onClick={()=>setDraft({...draft,paused:!draft.paused})}><i/></button></div></section><button className="btn btn-acid" onClick={save}>{saved?"Boundaries saved":"Save your boundaries"}<ArrowUpRight size={15}/></button></div>;
}

function MobileDock({ page, setPage }) { const links=[["home",Home,"Home"],["send",Send,"Send"],["savings",CircleDollarSign,"Save"],["assistant",MessageCircle,"Nyra"],["controls",Settings2,"Controls"]];return <nav className="mobile-dock">{links.map(([id,Icon,label])=><button className={`dock-item ${page===id?"active":""}`} key={id} onClick={()=>setPage(id)}><Icon size={18}/><span>{label}</span></button>)}</nav>; }

function Dashboard() { const [page,setPage]=useState("home"); const [policy,setPolicy]=useState(INITIAL_POLICY); const [wallet,setWallet]=useState(INITIAL_WALLET); const [transactions,setTransactions]=useState(TRANSACTIONS); const reviewCount=useMemo(()=>transactions.filter(t=>t.status==="review").length,[transactions]); const togglePause=()=>setPolicy(current=>({...current,paused:!current.paused})); return <div className="shell app"><Rail page={page} setPage={setPage} reviewCount={reviewCount}/><div className="app-main"><Topbar page={page} setPage={setPage}/><main className="content">{page==="home"&&<HomePage setPage={setPage} policy={policy} wallet={wallet} transactions={transactions} onTogglePause={togglePause}/>} {page==="send"&&<SendPage wallet={wallet} setWallet={setWallet} transactions={transactions} setTransactions={setTransactions} policy={policy}/>} {page==="savings"&&<SavingsPage wallet={wallet} setWallet={setWallet} transactions={transactions} setTransactions={setTransactions}/>} {page==="campus"&&<CampusPage setPage={setPage}/>} {page==="activity"&&<ActivityPage setPage={setPage} transactions={transactions}/>} {page==="assistant"&&<AssistantPage policy={policy}/>} {page==="controls"&&<ControlsPage policy={policy} setPolicy={setPolicy}/>}</main></div><MobileDock page={page} setPage={setPage}/></div>; }

export default function App(){const [view,setView]=useState("landing");return <><style>{CSS}</style>{view==="landing"?<Landing onStart={()=>setView("login")}/>:view==="login"?<Login onContinue={()=>setView("app")}/>:<Dashboard/>}</>;}
